-- Record the Mastodon migrations that `001_initial.sql` already builds.
--
-- `001_initial.sql` is a dump of a real Mastodon 4.6.0 database, so the schema it
-- creates is exactly what upstream's migrations produce -- but the ledger those
-- migrations write as they run, `public.schema_migrations`, came out of the dump
-- empty. Without it nothing can answer "which Mastodon schema is this database?":
-- not `eunha-schema check`, not the importer's preflight, and not a Rails
-- console pointed at the database, which would try to re-run all 588 of these
-- from scratch.
--
-- Everything through Mastodon 4.6.0 (20260611150940) is listed here.
-- Later releases add their own versions in their own migration; see
-- `008_mastodon_4_7_0.sql`. Regenerate with:
--
--     eunha-schema plan --to v4.6.0 --sql

ON CONFLICT (version) DO NOTHING;

-- Rails records which environment owns the schema; a Mastodon booted against
-- this database compares its own RAILS_ENV against it.
VALUES ('environment', 'production', now(), now())
ON CONFLICT (key) DO NOTHING;
